    prep3("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow-x: revert-layer; overflow-y: hidden; height: 25.4mm } html { scroll-padding: 0 62px 0.5lh 1.5em } #o { scroll-padding-bottom: 0.5lh; scroll-padding-inline-end: 25% } #b { scroll-padding-top: initial } #b { font-size: 39px } #b { animation: k 1s linear; animation-timeline: view(block) }", 1);
